xml.Script:
        clWhite        := 'F0F0F0';
        clSilver       := 'C0C0C0';
        clGray         := '808080';
        clBlack        := '202020';

        clCyan         := '00FFFF';
        clTeal         := '008080';
        clBlue         := '0000FF';
        clNavy         := '000080';

        clRed          := 'FF0000';
        clBrown        := '800000';
        clCoral        := 'FF7F50';
        clIndian       := 'CD5C5C';

        clYellow       := 'FFFF00';
        clOlive        := '808000';
        clOrange       := 'FF6000';
        clGolden       := 'DDBB20';

        clLime         := '00FF00';
        clGreen        := '008000';
        clDarkGreen    := '006400';
        clGreenYellow  := 'ADFF2F';

        clFuchsia      := 'FF00FF';
        clPurple       := '800080';
        clPink         := 'FF69B4';
        clPale         := 'DB7093';

        ColorsA[ 0] := clBlack;
        ColorsB[ 0] := clLime;
        ColorsA[ 1] := clFuchsia;
        ColorsB[ 1] := clGray;
        ColorsA[ 2] := clSilver;
        ColorsB[ 2] := clNavy;
        ColorsA[ 3] := clGolden;
        ColorsB[ 3] := clWhite;

        ColorsA[ 4] := clGreenYellow;
        ColorsB[ 4] := clYellow;
        ColorsA[ 5] := clGreen;
        ColorsB[ 5] := clPink;
        ColorsA[ 6] := clBlue;
        ColorsB[ 6] := clPurple;
        ColorsA[ 7] := clCyan;
        ColorsB[ 7] := clOrange;

        ColorsA[ 8] := clRed;
        ColorsB[ 8] := clDarkGreen;
        ColorsA[ 9] := clPale;
        ColorsB[ 9] := clBrown;
        ColorsA[10] := clCoral;
        ColorsB[10] := clTeal;
        ColorsA[11] := clOlive;
        ColorsB[11] := clIndian;

        R := 0.5;
        D := R / 3;
